// MARK: - Motion
// Springs are derived from stiffness / damping / mass: response = 2*pi / sqrt(k/m), dampingFraction = c / (2*sqrt(k*m)).

struct FlowdSpringSpec {
    let stiffness: Double
    let damping: Double
    let mass: Double
    let response: Double
    let dampingFraction: Double

    var animation: Animation {
        return Animation.spring(response: response, dampingFraction: dampingFraction)
    }
}

enum FlowdMotion {
    static let instant: TimeInterval = 0.08
    static let fast: TimeInterval = 0.15
    static let base: TimeInterval = 0.22
    static let slow: TimeInterval = 0.32
    static let slower: TimeInterval = 0.48
    static let hero: TimeInterval = 0.8
    static let stagger: TimeInterval = 0.04
    static let tapSpec: FlowdSpringSpec = FlowdSpringSpec(stiffness: 520, damping: 40, mass: 1, response: 0.276, dampingFraction: 0.877)
    static let tap: Animation = tapSpec.animation
    static let snappySpec: FlowdSpringSpec = FlowdSpringSpec(stiffness: 420, damping: 34, mass: 1, response: 0.307, dampingFraction: 0.83)
    static let snappy: Animation = snappySpec.animation
    static let smoothSpec: FlowdSpringSpec = FlowdSpringSpec(stiffness: 320, damping: 30, mass: 1, response: 0.351, dampingFraction: 0.839)
    static let smooth: Animation = smoothSpec.animation
    static let sheetSpec: FlowdSpringSpec = FlowdSpringSpec(stiffness: 380, damping: 36, mass: 1, response: 0.322, dampingFraction: 0.923)
    static let sheet: Animation = sheetSpec.animation
    static let gentleSpec: FlowdSpringSpec = FlowdSpringSpec(stiffness: 240, damping: 26, mass: 1, response: 0.406, dampingFraction: 0.839)
    static let gentle: Animation = gentleSpec.animation
    static let bouncySpec: FlowdSpringSpec = FlowdSpringSpec(stiffness: 300, damping: 22, mass: 1, response: 0.363, dampingFraction: 0.635)
    static let bouncy: Animation = bouncySpec.animation
    static func standard(_ duration: TimeInterval) -> Animation {
        return Animation.timingCurve(0.2, 0, 0, 1, duration: duration)
    }
    static func emphasized(_ duration: TimeInterval) -> Animation {
        return Animation.timingCurve(0.16, 1, 0.3, 1, duration: duration)
    }
    static func decelerate(_ duration: TimeInterval) -> Animation {
        return Animation.timingCurve(0, 0, 0.2, 1, duration: duration)
    }
    static func accelerate(_ duration: TimeInterval) -> Animation {
        return Animation.timingCurve(0.4, 0, 1, 1, duration: duration)
    }
    static func inOut(_ duration: TimeInterval) -> Animation {
        return Animation.timingCurve(0.65, 0, 0.35, 1, duration: duration)
    }
}

// MARK: - Typography
// SF Pro Rounded for display + every number, SF Pro for text, SF Mono for code. Sizes scale with Dynamic Type (ScaledMetric)
// unless `fixed`. Apply with `.flowdText(FlowdFont.title1)`.

struct FlowdTextStyle {
    let size: CGFloat
    let weight: Font.Weight
    let design: Font.Design
    let relativeTo: Font.TextStyle
    let trackingPt: CGFloat
    let lineHeight: CGFloat
    let uppercase: Bool
    let monospacedDigit: Bool
    let fixed: Bool

    /// Unscaled font (use where the modifier cannot be applied).
    var font: Font {
        let f: Font = Font.system(size: size, weight: weight, design: design)
        return monospacedDigit ? f.monospacedDigit() : f
    }

    /// Extra line spacing for a given point size (SF default line height is about 1.2 x size).
    func lineSpacing(for pointSize: CGFloat) -> CGFloat {
        return pointSize * (lineHeight - 1.2)
    }
}

struct FlowdTextModifier: ViewModifier {
    let style: FlowdTextStyle
    @ScaledMetric private var scaledSize: CGFloat

    init(style: FlowdTextStyle) {
        self.style = style
        self._scaledSize = ScaledMetric(wrappedValue: style.size, relativeTo: style.relativeTo)
    }

    func body(content: Content) -> some View {
        let pointSize: CGFloat = style.fixed ? style.size : scaledSize
        let base: Font = Font.system(size: pointSize, weight: style.weight, design: style.design)
        let font: Font = style.monospacedDigit ? base.monospacedDigit() : base
        let textCase: Text.Case? = style.uppercase ? Text.Case.uppercase : nil
        return content
            .font(font)
            .tracking(style.trackingPt)
            .lineSpacing(style.lineSpacing(for: pointSize))
            .textCase(textCase)
    }
}

extension View {
    func flowdText(_ style: FlowdTextStyle) -> some View {
        return modifier(FlowdTextModifier(style: style))
    }
}

